import os
import torch


class Config:
    # =========================================================================
    # General Settings
    # =========================================================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2  # Adjust based on available vCPUs

    # =========================================================================
    # Data Paths & Directories
    # =========================================================================
    # Metadata paths (Parquet files generated by metadata script)
    TRAIN_DATA_PATH = "./metadata/train.parquet"
    VAL_DATA_PATH = "./metadata/val.parquet"
    TEST_DATA_PATH = "./metadata/test.parquet"

    # Cache directory for processed tensors
    CACHE_DIR = "./working/idea_58/"
    os.makedirs(CACHE_DIR, exist_ok=True)

    # Output paths
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # =========================================================================
    # Data Dimensions
    # =========================================================================
    SEQ_LEN = 107
    PRED_LEN = 68

    # Scored targets: reactivity, deg_Mg_pH10, deg_Mg_50C
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = len(TARGET_COLS)

    # =========================================================================
    # Model Architecture: Vector-Scaled High-Capacity Wide-Stream BiGRU
    # =========================================================================
    # Embedding Dimensions
    EMBED_DIM_SEQ = 128  # Atomic Sequence (A, G, C, U)
    EMBED_DIM_LOOP = 64  # Predicted Loop Type
    EMBED_DIM_DIST = 64  # Signed Sinusoidal Pairing Distance

    # Total Input Dimension = 128 + 64 + 64 = 256
    INPUT_DIM = EMBED_DIM_SEQ + EMBED_DIM_LOOP + EMBED_DIM_DIST

    # Backbone Dimensions
    HIDDEN_DIM = 512  # Wide Stream Capacity
    NUM_LAYERS = 6  # Depth
    DROPOUT = 0.2  # Inter-layer dropout

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 32  # Strictly 32 for stability in low-data regime
    EPOCHS = 20  # Fixed budget
    LEARNING_RATE = 1e-3  # Standard AdamW starting point
    WEIGHT_DECAY = 1e-4  # Low weight decay to preserve recurrent signals
    GRAD_CLIP = 1.0  # Critical stabilizer for 512-width backbone

    # Loss Function
    LOSS_TYPE = "MSE"  # Mean Squared Error (L2)

    # Debugging
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SAMPLES = 100  # Number of samples if DEBUG is True
